-- V3 : 프로젝트별 AI 제공자 지정 (DEC-18, 2026-11-16 — docs/completed/ai-provider-ai3.md 15장). 행이 없으면 시스템 기본 제공자(TB_AI_STNG)를 쓴다.
-- 기존 데이터는 바꾸지 않는다 (지정 없는 상태로 시작). 예제(프로젝트 0)에 같은 테이블을 용어 → 물리 → 논리 → 매핑 → 관계 → 인덱스 → 업무 설명 순서로 넣는다.
create sequence SQ_PRJ_AI_STNG start with 1 increment by 50;
create table TB_PRJ_AI_STNG (
    PRJ_AI_STNG_SN bigint not null,
    PRJ_SN bigint not null,
    AI_PRVDR_SN bigint not null,
    MDL_NM varchar(255),
    REG_DT timestamp(6),
    MDFCN_DT timestamp(6),
    RGTR_ID varchar(255),
    MDFR_ID varchar(255),
    constraint PK_PRJ_AI_STNG primary key (PRJ_AI_STNG_SN)
);
create unique index UX_PRJ_AI_STNG_01 on TB_PRJ_AI_STNG (PRJ_SN);
alter table TB_PRJ_AI_STNG add constraint FK_PRJ_AI_STNG_01 foreign key (PRJ_SN) references TB_PRJ;
alter table TB_PRJ_AI_STNG add constraint FK_PRJ_AI_STNG_02 foreign key (AI_PRVDR_SN) references TB_AI_PRVDR;
comment on table TB_PRJ_AI_STNG is '프로젝트 AI 설정';
comment on column TB_PRJ_AI_STNG.PRJ_AI_STNG_SN is '프로젝트 AI 설정 일련번호';
comment on column TB_PRJ_AI_STNG.PRJ_SN is '프로젝트 일련번호';
comment on column TB_PRJ_AI_STNG.AI_PRVDR_SN is 'AI 제공자 일련번호';
comment on column TB_PRJ_AI_STNG.MDL_NM is '모델 명';
comment on column TB_PRJ_AI_STNG.REG_DT is '등록 일시';
comment on column TB_PRJ_AI_STNG.MDFCN_DT is '수정 일시';
comment on column TB_PRJ_AI_STNG.RGTR_ID is '등록자 아이디';
comment on column TB_PRJ_AI_STNG.MDFR_ID is '수정자 아이디';

-- ---------- 예제 : 데이터 사전 (새 용어 하나, 단어는 모두 있다) ----------
insert into TB_STD_TRM(STD_TRM_SN, PRJ_SN, ENCT_CYCL, TRM_NM, TRM_EXPLN, TRM_ENG_ABBR_NM, PBADMS_STD_CD_NM, JRSDC_INST_NM, STD_DMN_SN, APRV_YN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_STD_TRM'), 0, 1, '프로젝트_AI_설정_일련번호', '프로젝트 AI 설정 일련번호.', 'PRJ_AI_STNG_SN', null, null, d.STD_DMN_SN, true, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_STD_DMN d where d.PRJ_SN = 0 and d.DMN_NM = '일련번호L' and not exists (select 1 from TB_STD_TRM where PRJ_SN = 0 and TRM_NM = '프로젝트_AI_설정_일련번호');
insert into TB_STD_TRM_WORD(STD_TRM_WORD_SN, STD_TRM_SN, STD_WORD_SN, SORT_ORD, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_STD_TRM_WORD'), t.STD_TRM_SN, w.STD_WORD_SN, 1, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_STD_TRM t join TB_STD_WORD w on w.PRJ_SN = 0 and w.WORD_NM = '프로젝트' where t.PRJ_SN = 0 and t.TRM_NM = '프로젝트_AI_설정_일련번호' and not exists (select 1 from TB_STD_TRM_WORD x where x.STD_TRM_SN = t.STD_TRM_SN and x.SORT_ORD = 1);
insert into TB_STD_TRM_WORD(STD_TRM_WORD_SN, STD_TRM_SN, STD_WORD_SN, SORT_ORD, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_STD_TRM_WORD'), t.STD_TRM_SN, w.STD_WORD_SN, 2, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_STD_TRM t join TB_STD_WORD w on w.PRJ_SN = 0 and w.WORD_NM = 'AI' where t.PRJ_SN = 0 and t.TRM_NM = '프로젝트_AI_설정_일련번호' and not exists (select 1 from TB_STD_TRM_WORD x where x.STD_TRM_SN = t.STD_TRM_SN and x.SORT_ORD = 2);
insert into TB_STD_TRM_WORD(STD_TRM_WORD_SN, STD_TRM_SN, STD_WORD_SN, SORT_ORD, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_STD_TRM_WORD'), t.STD_TRM_SN, w.STD_WORD_SN, 3, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_STD_TRM t join TB_STD_WORD w on w.PRJ_SN = 0 and w.WORD_NM = '설정' where t.PRJ_SN = 0 and t.TRM_NM = '프로젝트_AI_설정_일련번호' and not exists (select 1 from TB_STD_TRM_WORD x where x.STD_TRM_SN = t.STD_TRM_SN and x.SORT_ORD = 3);
insert into TB_STD_TRM_WORD(STD_TRM_WORD_SN, STD_TRM_SN, STD_WORD_SN, SORT_ORD, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_STD_TRM_WORD'), t.STD_TRM_SN, w.STD_WORD_SN, 4, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_STD_TRM t join TB_STD_WORD w on w.PRJ_SN = 0 and w.WORD_NM = '일련번호' where t.PRJ_SN = 0 and t.TRM_NM = '프로젝트_AI_설정_일련번호' and not exists (select 1 from TB_STD_TRM_WORD x where x.STD_TRM_SN = t.STD_TRM_SN and x.SORT_ORD = 4);
