insert into TB_TBL(TBL_SN, PRJ_SN, SCHM_SN, TBL_NM, TBL_KORN_NM, TBL_EXPLN, MSTR_TBL_YN, SORT_ORD, APRV_YN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_TBL'), 0, s.SCHM_SN, 'TB_PRJ_AI_STNG', '프로젝트 AI 설정', '프로젝트별 AI 제공자 지정 (DEC-18) : 행이 있으면 그 프로젝트의 AI 기능이 이 제공자·모델을 쓰고, 없으면 시스템 기본 제공자를 쓴다. 다른 제공자로 대신하지 않는다', false, (select coalesce(max(SORT_ORD), 0) + 1 from TB_TBL where PRJ_SN = 0), true, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_SCHM s where s.PRJ_SN = 0 and s.BSC_YN = true and not exists (select 1 from TB_TBL where PRJ_SN = 0 and TBL_NM = 'TB_PRJ_AI_STNG');
insert into TB_COL(COL_SN, PRJ_SN, TBL_SN, TBL_NM, COL_NM, COL_EXPLN, DATA_TYPE_NM, MAX_LEN, DATA_PRCSN, DCPT_LEN, NULL_ALWNC_YN, BSC_VL, SORT_ORD, MSTR_DATA_YN, RFRNC_TBL_NM, ESNTL_YN, SNSTV_INFO_YN, PK_YN, UNQ_YN, IDX_YN, ENCPT_YN, APRV_YN, STD_TRM_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_COL'), 0, t.TBL_SN, 'TB_PRJ_AI_STNG', 'PRJ_AI_STNG_SN', '프로젝트 AI 설정 일련번호', 'BIGINT', null, null, null, false, null, 1, false, null, true, false, true, false, false, false, true, (select STD_TRM_SN from TB_STD_TRM where PRJ_SN = 0 and TRM_NM = '프로젝트_AI_설정_일련번호'), current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_TBL t where t.PRJ_SN = 0 and t.TBL_NM = 'TB_PRJ_AI_STNG' and not exists (select 1 from TB_COL c where c.TBL_SN = t.TBL_SN and c.COL_NM = 'PRJ_AI_STNG_SN');
