insert into TB_LGCL_ENTT(LGCL_ENTT_SN, PRJ_SN, LGCL_MDL_SN, ENTT_NM, ENTT_EXPLN, APRV_YN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_LGCL_ENTT'), 0, m.LGCL_MDL_SN, '프로젝트 AI 설정', '프로젝트별 AI 제공자 지정 (DEC-18) : 행이 있으면 그 프로젝트의 AI 기능이 이 제공자·모델을 쓰고, 없으면 시스템 기본 제공자를 쓴다. 다른 제공자로 대신하지 않는다', true, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_LGCL_MDL m where m.PRJ_SN = 0 and m.MDL_NM = 'LEXORMA' and not exists (select 1 from TB_LGCL_ENTT e where e.LGCL_MDL_SN = m.LGCL_MDL_SN and e.ENTT_NM = '프로젝트 AI 설정');
