insert into TB_LGCL_ATRB(LGCL_ATRB_SN, LGCL_ENTT_SN, ATRB_NM, ATRB_EXPLN, DATA_TYPE_NM, ESNTL_YN, SORT_ORD, STD_TRM_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_LGCL_ATRB'), e.LGCL_ENTT_SN, 'AI 제공자 일련번호', null, null, true, 3, (select STD_TRM_SN from TB_STD_TRM where PRJ_SN = 0 and TRM_NM = 'AI_제공자_일련번호'), current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_LGCL_ENTT e where e.LGCL_MDL_SN = (select LGCL_MDL_SN from TB_LGCL_MDL where PRJ_SN = 0 and MDL_NM = 'LEXORMA') and e.ENTT_NM = '프로젝트 AI 설정' and not exists (select 1 from TB_LGCL_ATRB a where a.LGCL_ENTT_SN = e.LGCL_ENTT_SN and a.ATRB_NM = 'AI 제공자 일련번호');
