insert into TB_LGCL_ATRB(LGCL_ATRB_SN, LGCL_ENTT_SN, ATRB_NM, ATRB_EXPLN, DATA_TYPE_NM, ESNTL_YN, SORT_ORD, STD_TRM_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_LGCL_ATRB'), e.LGCL_ENTT_SN, '등록 일시', null, null, false, 5, (select STD_TRM_SN from TB_STD_TRM where PRJ_SN = 0 and TRM_NM = '등록_일시'), current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_LGCL_ENTT e where e.LGCL_MDL_SN = (select LGCL_MDL_SN from TB_LGCL_MDL where PRJ_SN = 0 and MDL_NM = 'LEXORMA') and e.ENTT_NM = '프로젝트 AI 설정' and not exists (select 1 from TB_LGCL_ATRB a where a.LGCL_ENTT_SN = e.LGCL_ENTT_SN and a.ATRB_NM = '등록 일시');
insert into TB_LGCL_ATRB(LGCL_ATRB_SN, LGCL_ENTT_SN, ATRB_NM, ATRB_EXPLN, DATA_TYPE_NM, ESNTL_YN, SORT_ORD, STD_TRM_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_LGCL_ATRB'), e.LGCL_ENTT_SN, '수정 일시', null, null, false, 6, (select STD_TRM_SN from TB_STD_TRM where PRJ_SN = 0 and TRM_NM = '수정_일시'), current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_LGCL_ENTT e where e.LGCL_MDL_SN = (select LGCL_MDL_SN from TB_LGCL_MDL where PRJ_SN = 0 and MDL_NM = 'LEXORMA') and e.ENTT_NM = '프로젝트 AI 설정' and not exists (select 1 from TB_LGCL_ATRB a where a.LGCL_ENTT_SN = e.LGCL_ENTT_SN and a.ATRB_NM = '수정 일시');
insert into TB_LGCL_ATRB(LGCL_ATRB_SN, LGCL_ENTT_SN, ATRB_NM, ATRB_EXPLN, DATA_TYPE_NM, ESNTL_YN, SORT_ORD, STD_TRM_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_LGCL_ATRB'), e.LGCL_ENTT_SN, '등록자 아이디', null, null, false, 7, (select STD_TRM_SN from TB_STD_TRM where PRJ_SN = 0 and TRM_NM = '등록자_아이디'), current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_LGCL_ENTT e where e.LGCL_MDL_SN = (select LGCL_MDL_SN from TB_LGCL_MDL where PRJ_SN = 0 and MDL_NM = 'LEXORMA') and e.ENTT_NM = '프로젝트 AI 설정' and not exists (select 1 from TB_LGCL_ATRB a where a.LGCL_ENTT_SN = e.LGCL_ENTT_SN and a.ATRB_NM = '등록자 아이디');
insert into TB_LGCL_ATRB(LGCL_ATRB_SN, LGCL_ENTT_SN, ATRB_NM, ATRB_EXPLN, DATA_TYPE_NM, ESNTL_YN, SORT_ORD, STD_TRM_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_LGCL_ATRB'), e.LGCL_ENTT_SN, '수정자 아이디', null, null, false, 8, (select STD_TRM_SN from TB_STD_TRM where PRJ_SN = 0 and TRM_NM = '수정자_아이디'), current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_LGCL_ENTT e where e.LGCL_MDL_SN = (select LGCL_MDL_SN from TB_LGCL_MDL where PRJ_SN = 0 and MDL_NM = 'LEXORMA') and e.ENTT_NM = '프로젝트 AI 설정' and not exists (select 1 from TB_LGCL_ATRB a where a.LGCL_ENTT_SN = e.LGCL_ENTT_SN and a.ATRB_NM = '수정자 아이디');
insert into TB_LGCL_IDNTFR(LGCL_IDNTFR_SN, LGCL_ENTT_SN, IDNTFR_NM, BSC_YN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_LGCL_IDNTFR'), e.LGCL_ENTT_SN, '프로젝트 AI 설정 식별자', true, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_LGCL_ENTT e where e.LGCL_MDL_SN = (select LGCL_MDL_SN from TB_LGCL_MDL where PRJ_SN = 0 and MDL_NM = 'LEXORMA') and e.ENTT_NM = '프로젝트 AI 설정' and not exists (select 1 from TB_LGCL_IDNTFR i where i.LGCL_ENTT_SN = e.LGCL_ENTT_SN and i.BSC_YN = true);
insert into TB_LGCL_IDNTFR_ATRB(LGCL_IDNTFR_ATRB_SN, LGCL_IDNTFR_SN, LGCL_ATRB_SN, SORT_ORD) select nextval('SQ_LGCL_IDNTFR_ATRB'), i.LGCL_IDNTFR_SN, a.LGCL_ATRB_SN, 1 from TB_LGCL_IDNTFR i join TB_LGCL_ATRB a on a.LGCL_ENTT_SN = i.LGCL_ENTT_SN and a.ATRB_NM = '프로젝트 AI 설정 일련번호' where i.LGCL_ENTT_SN = (select LGCL_ENTT_SN from TB_LGCL_ENTT where LGCL_MDL_SN = (select LGCL_MDL_SN from TB_LGCL_MDL where PRJ_SN = 0 and MDL_NM = 'LEXORMA') and ENTT_NM = '프로젝트 AI 설정') and i.IDNTFR_NM = '프로젝트 AI 설정 식별자' and not exists (select 1 from TB_LGCL_IDNTFR_ATRB x where x.LGCL_IDNTFR_SN = i.LGCL_IDNTFR_SN);
-- ---------- 예제 : 논리 ↔ 물리 매핑 (이 엔터티·테이블만) ----------
insert into TB_ENTT_TBL_MPNG(ENTT_TBL_MPNG_SN, PRJ_SN, LGCL_ENTT_SN, TBL_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID)
select nextval('SQ_ENTT_TBL_MPNG'), 0, e.LGCL_ENTT_SN, t.TBL_SN, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM'
from TB_LGCL_ENTT e
join TB_LGCL_MDL m on m.LGCL_MDL_SN = e.LGCL_MDL_SN and m.PRJ_SN = 0 and m.MDL_NM = 'LEXORMA'
join TB_TBL t on t.PRJ_SN = 0 and t.TBL_NM = 'TB_PRJ_AI_STNG'
where e.PRJ_SN = 0 and e.ENTT_NM = '프로젝트 AI 설정'
  and not exists (select 1 from TB_ENTT_TBL_MPNG x where x.LGCL_ENTT_SN = e.LGCL_ENTT_SN)
  and not exists (select 1 from TB_ENTT_TBL_MPNG x where x.TBL_SN = t.TBL_SN);
insert into TB_ATRB_COL_MPNG(ATRB_COL_MPNG_SN, ENTT_TBL_MPNG_SN, LGCL_ATRB_SN, COL_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID)
select nextval('SQ_ATRB_COL_MPNG'), mp.ENTT_TBL_MPNG_SN, a.LGCL_ATRB_SN, c.COL_SN, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM'
from TB_ENTT_TBL_MPNG mp
join TB_LGCL_ENTT e on e.LGCL_ENTT_SN = mp.LGCL_ENTT_SN and e.ENTT_NM = '프로젝트 AI 설정'
join TB_TBL t on t.TBL_SN = mp.TBL_SN and t.TBL_NM = 'TB_PRJ_AI_STNG'
join TB_LGCL_ATRB a on a.LGCL_ENTT_SN = e.LGCL_ENTT_SN
join TB_COL c on c.TBL_SN = t.TBL_SN and c.STD_TRM_SN = a.STD_TRM_SN
where mp.PRJ_SN = 0
  and not exists (select 1 from TB_ATRB_COL_MPNG x where x.LGCL_ATRB_SN = a.LGCL_ATRB_SN)
  and not exists (select 1 from TB_ATRB_COL_MPNG x where x.COL_SN = c.COL_SN);
-- ---------- 예제 : 관계 (V3 의 FK 그대로) ----------
insert into TB_TBL_REL(REL_SN, PRJ_SN, ORGNL_TBL_SN, TRGT_TBL_SN, REL_NM, REL_TYPE_CD, REL_SRC_CD, DRVN_COL_SN, APRV_YN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_TBL_REL'), 0, o.TBL_SN, t.TBL_SN, 'FK_PRJ_AI_STNG_01', 'FK', 'USER', null, true, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_TBL o join TB_TBL t on t.PRJ_SN = 0 and t.TBL_NM = 'TB_PRJ' where o.PRJ_SN = 0 and o.TBL_NM = 'TB_PRJ_AI_STNG' and not exists (select 1 from TB_TBL_REL r where r.PRJ_SN = 0 and r.ORGNL_TBL_SN = o.TBL_SN and upper(r.REL_NM) = 'FK_PRJ_AI_STNG_01');
insert into TB_TBL_REL_COL(REL_COL_SN, REL_SN, ORGNL_COL_SN, TRGT_COL_SN, COL_ORD) select nextval('SQ_TBL_REL_COL'), r.REL_SN, oc.COL_SN, tc.COL_SN, 1 from TB_TBL_REL r join TB_TBL o on o.TBL_SN = r.ORGNL_TBL_SN and o.PRJ_SN = 0 and o.TBL_NM = 'TB_PRJ_AI_STNG' join TB_COL oc on oc.TBL_SN = r.ORGNL_TBL_SN and oc.COL_NM = 'PRJ_SN' join TB_COL tc on tc.TBL_SN = r.TRGT_TBL_SN and tc.COL_NM = 'PRJ_SN' where r.PRJ_SN = 0 and upper(r.REL_NM) = 'FK_PRJ_AI_STNG_01' and not exists (select 1 from TB_TBL_REL_COL x where x.REL_SN = r.REL_SN and x.COL_ORD = 1);
insert into TB_TBL_REL(REL_SN, PRJ_SN, ORGNL_TBL_SN, TRGT_TBL_SN, REL_NM, REL_TYPE_CD, REL_SRC_CD, DRVN_COL_SN, APRV_YN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_TBL_REL'), 0, o.TBL_SN, t.TBL_SN, 'FK_PRJ_AI_STNG_02', 'FK', 'USER', null, true, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_TBL o join TB_TBL t on t.PRJ_SN = 0 and t.TBL_NM = 'TB_AI_PRVDR' where o.PRJ_SN = 0 and o.TBL_NM = 'TB_PRJ_AI_STNG' and not exists (select 1 from TB_TBL_REL r where r.PRJ_SN = 0 and r.ORGNL_TBL_SN = o.TBL_SN and upper(r.REL_NM) = 'FK_PRJ_AI_STNG_02');
insert into TB_TBL_REL_COL(REL_COL_SN, REL_SN, ORGNL_COL_SN, TRGT_COL_SN, COL_ORD) select nextval('SQ_TBL_REL_COL'), r.REL_SN, oc.COL_SN, tc.COL_SN, 1 from TB_TBL_REL r join TB_TBL o on o.TBL_SN = r.ORGNL_TBL_SN and o.PRJ_SN = 0 and o.TBL_NM = 'TB_PRJ_AI_STNG' join TB_COL oc on oc.TBL_SN = r.ORGNL_TBL_SN and oc.COL_NM = 'AI_PRVDR_SN' join TB_COL tc on tc.TBL_SN = r.TRGT_TBL_SN and tc.COL_NM = 'AI_PRVDR_SN' where r.PRJ_SN = 0 and upper(r.REL_NM) = 'FK_PRJ_AI_STNG_02' and not exists (select 1 from TB_TBL_REL_COL x where x.REL_SN = r.REL_SN and x.COL_ORD = 1);
-- ---------- 예제 : 논리 관계 (물리 FK 하나에 하나, V1 과 같은 규칙) ----------
insert into TB_LGCL_REL(LGCL_REL_SN, PRJ_SN, LGCL_MDL_SN, ORGNL_ENTT_SN, TRGT_ENTT_SN, REL_NM, REL_EXPLN, IDNTF_YN, ORGNL_MIN_CNT, ORGNL_MAX_CNT, TRGT_MIN_CNT, TRGT_MAX_CNT, APRV_YN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_LGCL_REL'), 0, pe.LGCL_MDL_SN, pe.LGCL_ENTT_SN, ce.LGCL_ENTT_SN, pt.TBL_KORN_NM, ct.TBL_KORN_NM || '의 ' || (select c.COL_EXPLN from TB_COL c where c.TBL_SN = ct.TBL_SN and c.COL_NM = 'PRJ_SN') || ' 로 ' || pt.TBL_KORN_NM || ' 을(를) 참조', case when exists (select 1 from TB_COL c where c.TBL_SN = ct.TBL_SN and c.COL_NM in ('PRJ_SN') and c.PK_YN = false) then false else true end, case when exists (select 1 from TB_COL c where c.TBL_SN = ct.TBL_SN and c.COL_NM in ('PRJ_SN') and c.NULL_ALWNC_YN = true) then 0 else 1 end, 1, 0, null, true, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_TBL ct join TB_TBL pt on pt.PRJ_SN = 0 and pt.TBL_NM = 'TB_PRJ' join TB_LGCL_ENTT ce on ce.LGCL_MDL_SN = (select LGCL_MDL_SN from TB_LGCL_MDL where PRJ_SN = 0 and MDL_NM = 'LEXORMA') and ce.ENTT_NM = ct.TBL_KORN_NM join TB_LGCL_ENTT pe on pe.LGCL_MDL_SN = ce.LGCL_MDL_SN and pe.ENTT_NM = pt.TBL_KORN_NM where ct.PRJ_SN = 0 and ct.TBL_NM = 'TB_PRJ_AI_STNG' and not exists (select 1 from TB_LGCL_REL x where x.LGCL_MDL_SN = ce.LGCL_MDL_SN and x.ORGNL_ENTT_SN = pe.LGCL_ENTT_SN and x.TRGT_ENTT_SN = ce.LGCL_ENTT_SN and x.REL_EXPLN = ct.TBL_KORN_NM || '의 ' || (select c.COL_EXPLN from TB_COL c where c.TBL_SN = ct.TBL_SN and c.COL_NM = 'PRJ_SN') || ' 로 ' || pt.TBL_KORN_NM || ' 을(를) 참조');
insert into TB_LGCL_REL(LGCL_REL_SN, PRJ_SN, LGCL_MDL_SN, ORGNL_ENTT_SN, TRGT_ENTT_SN, REL_NM, REL_EXPLN, IDNTF_YN, ORGNL_MIN_CNT, ORGNL_MAX_CNT, TRGT_MIN_CNT, TRGT_MAX_CNT, APRV_YN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_LGCL_REL'), 0, pe.LGCL_MDL_SN, pe.LGCL_ENTT_SN, ce.LGCL_ENTT_SN, pt.TBL_KORN_NM, ct.TBL_KORN_NM || '의 ' || (select c.COL_EXPLN from TB_COL c where c.TBL_SN = ct.TBL_SN and c.COL_NM = 'AI_PRVDR_SN') || ' 로 ' || pt.TBL_KORN_NM || ' 을(를) 참조', case when exists (select 1 from TB_COL c where c.TBL_SN = ct.TBL_SN and c.COL_NM in ('AI_PRVDR_SN') and c.PK_YN = false) then false else true end, case when exists (select 1 from TB_COL c where c.TBL_SN = ct.TBL_SN and c.COL_NM in ('AI_PRVDR_SN') and c.NULL_ALWNC_YN = true) then 0 else 1 end, 1, 0, null, true, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_TBL ct join TB_TBL pt on pt.PRJ_SN = 0 and pt.TBL_NM = 'TB_AI_PRVDR' join TB_LGCL_ENTT ce on ce.LGCL_MDL_SN = (select LGCL_MDL_SN from TB_LGCL_MDL where PRJ_SN = 0 and MDL_NM = 'LEXORMA') and ce.ENTT_NM = ct.TBL_KORN_NM join TB_LGCL_ENTT pe on pe.LGCL_MDL_SN = ce.LGCL_MDL_SN and pe.ENTT_NM = pt.TBL_KORN_NM where ct.PRJ_SN = 0 and ct.TBL_NM = 'TB_PRJ_AI_STNG' and not exists (select 1 from TB_LGCL_REL x where x.LGCL_MDL_SN = ce.LGCL_MDL_SN and x.ORGNL_ENTT_SN = pe.LGCL_ENTT_SN and x.TRGT_ENTT_SN = ce.LGCL_ENTT_SN and x.REL_EXPLN = ct.TBL_KORN_NM || '의 ' || (select c.COL_EXPLN from TB_COL c where c.TBL_SN = ct.TBL_SN and c.COL_NM = 'AI_PRVDR_SN') || ' 로 ' || pt.TBL_KORN_NM || ' 을(를) 참조');
-- ---------- 예제 : 인덱스 (V3 의 create unique index 그대로) ----------
insert into TB_TBL_IDX(IDX_SN, PRJ_SN, TBL_SN, IDX_NM, IDX_TYPE_NM, UNQ_YN, APRV_YN, IDX_SRC_CD, DRVN_COL_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID)
select nextval('SQ_TBL_IDX'), 0, t.TBL_SN, 'UX_PRJ_AI_STNG_01', null, true, true, 'USER', null, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM'
from TB_TBL t where t.PRJ_SN = 0 and t.TBL_NM = 'TB_PRJ_AI_STNG' and not exists (select 1 from TB_TBL_IDX i where i.TBL_SN = t.TBL_SN and i.IDX_NM = 'UX_PRJ_AI_STNG_01');
insert into TB_TBL_IDX_COL(IDX_COL_SN, IDX_SN, COL_SN, COL_ORD)
select nextval('SQ_TBL_IDX_COL'), i.IDX_SN, c.COL_SN, 1
from TB_TBL t join TB_TBL_IDX i on i.TBL_SN = t.TBL_SN and i.IDX_NM = 'UX_PRJ_AI_STNG_01' join TB_COL c on c.TBL_SN = t.TBL_SN and c.COL_NM = 'PRJ_SN'
where t.PRJ_SN = 0 and t.TBL_NM = 'TB_PRJ_AI_STNG' and not exists (select 1 from TB_TBL_IDX_COL x where x.IDX_SN = i.IDX_SN);
-- ---------- 예제 : 업무 설명 (예제 테이블·컬럼은 모두 채운다) ----------
update TB_TBL set TASK_EXPLN = '프로젝트가 시스템 기본과 다른 AI 제공자·모델을 쓰도록 지정한다. 지정이 없으면 시스템 기본 제공자를 쓰고, 지정한 제공자를 쓸 수 없으면 다른 제공자로 대신하지 않고 AI 기능을 거절한다.' where PRJ_SN = 0 and TBL_NM = 'TB_PRJ_AI_STNG' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '프로젝트 AI 설정을 구분하는 내부 번호.' where PRJ_SN = 0 and TBL_NM = 'TB_PRJ_AI_STNG' and COL_NM = 'PRJ_AI_STNG_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '설정이 속한 프로젝트. 프로젝트마다 한 행만 둔다.' where PRJ_SN = 0 and TBL_NM = 'TB_PRJ_AI_STNG' and COL_NM = 'PRJ_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '이 프로젝트가 쓸 AI 제공자. 지정된 제공자는 지울 수 없다.' where PRJ_SN = 0 and TBL_NM = 'TB_PRJ_AI_STNG' and COL_NM = 'AI_PRVDR_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '이 프로젝트가 쓸 모델. 비우면 제공자의 기본 모델을 쓴다.' where PRJ_SN = 0 and TBL_NM = 'TB_PRJ_AI_STNG' and COL_NM = 'MDL_NM' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 등록한 일시 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_PRJ_AI_STNG' and COL_NM = 'REG_DT' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 마지막으로 수정한 일시 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_PRJ_AI_STNG' and COL_NM = 'MDFCN_DT' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 등록한 사용자 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_PRJ_AI_STNG' and COL_NM = 'RGTR_ID' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 마지막으로 수정한 사용자 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_PRJ_AI_STNG' and COL_NM = 'MDFR_ID' and TASK_EXPLN is null;
